    void testExecuteRule_NegativeAmountValidation() {
        Copau01cRequest request = new Copau01cRequest(
            "00000000001",
            new BigDecimal("-50.00"),
            "DEBIT",
            "TXN-NEG-VAL",
            "4000123456789010",
